import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"复制延迟与读己之写","description":"","frontmatter":{"title":"复制延迟与读己之写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/replication-lag-rmw.md","filePath":"cs/replication-lag-rmw.md","lastUpdated":1789023840000}'),B={name:"cs/replication-lag-rmw.md"};function m(h,a,E,_,A,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="复制延迟与读己之写" tabindex="-1">复制延迟与读己之写 <a class="header-anchor" href="#复制延迟与读己之写" aria-label="Permalink to &quot;复制延迟与读己之写&quot;">​</a></h1><div class="epigraph"><p>写主读备时，用户可能读不到刚写的行。读己之写是会话合同，不是隔离级别自带的礼物。</p><footer>—— 据 Bailis et al. 对会话保证；Gray 复制；半同步对照</footer></div><p><a href="/cs/semi-sync-replication">上一课</a>让提交等备库。本课即使 ACK 了 apply 仍可能落后，异步更甚。事务进阶在此封口。缺口是会话：应用写主后立刻读备，看见旧快照。主干复制课点到延迟；进阶钉 <strong>read-your-writes</strong> 及常见补丁（粘滞、等 LSN、只读走主）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隔离级别描述单副本上的并发。多副本上，因果与会话要另写。读己之写：同一客户端写提交后，其后续读应看见该写（或更新）。单调读：不回到更旧快照。缺口是备库 apply 落后于主的提交 LSN。</p><p>半同步保证备库<strong>收到</strong>，不保证<strong>已 apply</strong>，更不保证<strong>你的下一次读打到该备</strong>。负载均衡随机备库会打破单调读。</p><p><span class="marginnote">会话保证文献（read-your-writes、monotonic reads）。本课工程补丁。分布式数据库课会把因果与 TrueTime 再升级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写后读主：简单，备库只承担落后只读。会话粘滞：同一会话钉同一备，并记录主上 <code>commit_lsn</code>，读前等备库 <code>replay &gt;= lsn</code>（或超时走主）。令牌：把 LSN 放进用户 cookie。</p><p>CDC 下游更滞后，不能当读己之写存储除非等。</p>',10)),(e(),n(c,null,{default:t(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E4%B8%BB%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20LSN%5B%22%E8%AE%B0%E4%B8%8B%20commit%20LSN%22%5D%0A%20%20R%5B%22%E8%AF%BB%22%5D%20--%3E%20WAIT%5B%22%E5%A4%87%E5%BA%93%20replay%20%E8%BF%BD%E4%B8%8A%22%5D%0A%20%20R%20--%3E%20MASTER%5B%22%E6%88%96%E8%AF%BB%E4%B8%BB%22%5D%0A%20%20LB%5B%22%E9%9A%8F%E6%9C%BA%E5%A4%87%E5%BA%93%22%5D%20--%3E%20BRK%5B%22%E6%89%93%E7%A0%B4%E5%8D%95%E8%B0%83%E8%AF%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连接池：还池丢会话粘滞则保证碎——连接池课的状态泄漏在复制层重现。只读事务快照若取自落后备库，分析一致但是陈旧，要标 SLA。</p><p>故障：等 LSN 超时应失败可见，不能悄悄返回旧行当成功。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲分片键。也不把读己之写当线性一致。恢复复制续结束：从 ARIES 到会话读。</p><p>后课默认：读备库要会话合同；默认教学写后读主。下一课程分布式：分片键与再平衡，故障域变成多主存储。</p><p>延迟是复制的物理；会话保证是应用看见的逻辑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读备库需显式读己之写：等 LSN、粘滞或读主。</li><li>随机负载均衡破坏单调读；池必须带会话状态。</li><li>下一课程分片键与再平衡。</li><li>出处：会话保证文献；Gray；复制实践。</li></ul>',9))])}const T=i(B,[["render",m]]);export{S as __pageData,T as default};
